// =====================================================================
// Sumário Dinâmico - Controller Principal
// Port da macro VBA para Office.js (TypeScript)
// =====================================================================
import { ConfigManager } from "./configManager";
import { lerSecoes } from "./secoes";
const DEFAULT_CONFIG = {
    posicaoPadrao: "rodape",
    topoFaixa: "clara",
    topoFaixaAltCm: 1.15,
    margemEsq: 28,
    reservaDir: 70,
    fonte: "Calibri",
    tamFonte: 12,
    separador: " · ",
    rAtual: "#FFFFFF",
    rPassada: "#AAAAAA",
    rFutura: "#737373",
    cFundo: "#EDEDED",
    cAtual: "#333333",
    cPassada: "#8A8A8A",
    cFutura: "#B0B0B0",
    eFundo: "#3D3D3D",
    tAtual: "#333333",
    tPassada: "#9A9A9A",
    tFutura: "#C4C4C4",
    corDestaque: "#BA7517",
    espLinha: 3,
    mostrarLinha: true,
    animarProgresso: true,
    durAnimacao: 0.5,
    travarElementos: true,
    modoCompactoAuto: true,
    prefixoIgnorar: "#",
    layoutSemSumario: "Divisor de seção",
};
const TAG_NOME = "SUMARIO";
const TAG_ANTIGA = "ROTEIRO";
// Constantes de geometria (frações da altura do slide)
const TITULO_BASE_REL = 0.107;
const RODAPE_TOPO_REL = 0.934;
const RODAPE_ALT_REL = 0.066;
const TOPO_FOLGA_REL = 0.012;
const TOPO_ALT_REL = 0.045;
// A API não mede texto (não há BoundWidth): estima a largura média de um
// caractere como fração do tamanho da fonte para decidir o modo compacto
const LARGURA_MEDIA_CARACTERE = 0.52;
// Tamanho padrão 16:9 em pontos, usado se pageSetup (PowerPointApi 1.10) não existir
const W_PADRAO = 960;
const H_PADRAO = 540;
export class SumarioController {
    /** Sem `ui` (botões da fita) o controller roda sem painel */
    constructor(ui = null) {
        this.initialized = false;
        this.configManager = new ConfigManager();
        this.ui = ui;
        this.config = { ...DEFAULT_CONFIG };
    }
    async initialize() {
        if (this.initialized)
            return;
        await this.configManager.load();
        this.config = { ...DEFAULT_CONFIG, ...this.configManager.getConfig() };
        this.initialized = true;
        if (this.ui) {
            this.ui.bindControls(this.config, (updated) => this.onConfigChange(updated));
            await this.refreshSectionsList();
            this.ui.showToast("Sumário Dinâmico carregado", "success");
        }
    }
    onConfigChange(updated) {
        this.config = { ...this.config, ...updated };
        this.configManager.save(this.config);
    }
    // =====================================================================
    // AÇÕES PRINCIPAIS
    // =====================================================================
    async gerarSumario(posicao) {
        await this.comStatus("Gerando sumário...", `Sumário gerado no ${posicao === "topo" ? "topo" : "rodapé"}`, () => this.executar(posicao));
    }
    async atualizarSumario() {
        // Configurações podem ter sido alteradas pelo painel (outra instância)
        this.config = { ...DEFAULT_CONFIG, ...this.configManager.getConfig() };
        await this.comStatus("Atualizando sumário...", "Sumário atualizado", () => this.executar(this.config.posicaoPadrao));
    }
    async removerSumarioTodos() {
        await this.comStatus("Removendo sumário...", "Sumário removido", () => PowerPoint.run(async (context) => {
            const slides = context.presentation.slides;
            slides.load("items");
            await context.sync();
            await this.removerElementos(context, slides.items);
            await context.sync();
        }));
    }
    async comStatus(trabalhando, sucesso, acao) {
        this.ui?.setStatus("working", trabalhando);
        try {
            await acao();
            this.ui?.showToast(sucesso, "success");
            this.ui?.setStatus("connected", "Pronto");
        }
        catch (error) {
            this.ui?.showToast(`Erro: ${error instanceof Error ? error.message : error}`, "error");
            this.ui?.setStatus("connected", "Erro");
            throw error;
        }
    }
    // =====================================================================
    // LÓGICA PRINCIPAL
    // =====================================================================
    async executar(posicao) {
        const estrutura = await lerSecoes();
        const secoesValidas = estrutura.secoes.map((sec, i) => ({
            index: i,
            name: sec.name,
            slideCount: sec.slideCount,
            ignored: this.secaoIgnorada(sec.name),
        }));
        if (secoesValidas.length === 0) {
            throw new Error("A apresentação não tem seções. Crie seções (botão direito entre slides → Adicionar Seção).");
        }
        const secoesParaSumario = secoesValidas.filter((s) => !s.ignored);
        if (secoesParaSumario.length === 0) {
            throw new Error("Nenhuma seção válida para sumário. Verifique o prefixo de exclusão.");
        }
        await PowerPoint.run(async (context) => {
            const slides = context.presentation.slides;
            slides.load("items/id,items/layout/name");
            const tamanho = this.carregarTamanhoSlide(context);
            await context.sync();
            if (slides.items.length !== estrutura.secaoDoSlide.length) {
                throw new Error("A apresentação mudou durante a leitura. Tente novamente.");
            }
            const { W, H } = tamanho();
            // Determinar elegibilidade de cada slide
            const slidesInfo = [];
            let totalElegiveis = 0;
            for (let i = 0; i < slides.items.length; i++) {
                const layoutName = slides.items[i].layout.name;
                const sectionIdx = estrutura.secaoDoSlide[i];
                const secao = secoesValidas[sectionIdx];
                const elegivel = !!secao && !secao.ignored && layoutName !== this.config.layoutSemSumario;
                let pos = 0;
                if (elegivel) {
                    totalElegiveis++;
                    pos = totalElegiveis;
                }
                slidesInfo.push({ index: i, sectionIndex: sectionIdx, layoutName, eligible: elegivel, position: pos });
            }
            if (totalElegiveis === 0) {
                throw new Error("Nenhum slide elegível para receber sumário.");
            }
            await this.removerElementos(context, slides.items);
            for (const slideInfo of slidesInfo) {
                if (!slideInfo.eligible)
                    continue;
                const slide = slides.items[slideInfo.index];
                const kAtual = secoesParaSumario.findIndex((s) => s.index === slideInfo.sectionIndex) + 1;
                this.desenharSumarioSlide(slide, secoesParaSumario, kAtual, posicao, W, H);
                if (this.config.mostrarLinha) {
                    this.desenharProgressoSlide(slide, slideInfo.position, totalElegiveis, posicao, W, H);
                }
            }
            await context.sync();
        });
    }
    secaoIgnorada(nome) {
        return this.config.prefixoIgnorar !== "" && nome.startsWith(this.config.prefixoIgnorar);
    }
    carregarTamanhoSlide(context) {
        if (Office.context.requirements.isSetSupported("PowerPointApi", "1.10")) {
            const pageSetup = context.presentation.pageSetup;
            pageSetup.load("slideWidth,slideHeight");
            return () => ({ W: pageSetup.slideWidth, H: pageSetup.slideHeight });
        }
        return () => ({ W: W_PADRAO, H: H_PADRAO });
    }
    // =====================================================================
    // DESENHO DO SUMÁRIO
    // =====================================================================
    desenharSumarioSlide(slide, secoes, kAtual, posicao, W, H) {
        // Faixa de fundo no topo
        if (posicao === "topo" && this.config.topoFaixa !== "nenhuma") {
            this.criarFaixaTopo(slide, W, H);
        }
        const geo = this.calcularGeometriaECores(posicao, W, H);
        // Modo compacto se os nomes completos não couberem
        let compacto = false;
        if (this.config.modoCompactoAuto) {
            const { txt } = this.montarTextoSumario(secoes, secoes.length, kAtual, false);
            compacto = txt.length * this.config.tamFonte * LARGURA_MEDIA_CARACTERE > geo.larg;
        }
        this.criarTextoSumario(slide, secoes, secoes.length, kAtual, compacto, geo);
    }
    criarFaixaTopo(slide, W, H) {
        const TOPO_FAIXA_ALT_PT = (this.config.topoFaixaAltCm / 2.54) * 72;
        const fx = slide.shapes.addGeometricShape("Rectangle", {
            left: 0,
            top: H * TITULO_BASE_REL,
            width: W,
            height: TOPO_FAIXA_ALT_PT,
        });
        fx.name = "FaixaSumario";
        fx.tags.add(TAG_NOME, "1");
        fx.fill.setSolidColor(this.config.topoFaixa === "escura" ? this.config.eFundo : this.config.cFundo);
        fx.lineFormat.visible = false;
        return fx;
    }
    criarTextoSumario(slide, secoes, n, kAtual, compacto, geo) {
        const { txt, ini, tam } = this.montarTextoSumario(secoes, n, kAtual, compacto);
        const shp = slide.shapes.addTextBox(txt, { left: geo.x, top: geo.y, width: geo.larg, height: geo.alt });
        shp.name = "Sumario";
        shp.tags.add(TAG_NOME, "1");
        const tf = shp.textFrame;
        tf.autoSizeSetting = "AutoSizeNone";
        tf.wordWrap = false;
        tf.topMargin = 0;
        tf.bottomMargin = 0;
        tf.leftMargin = 0;
        tf.rightMargin = 0;
        tf.verticalAlignment = "Middle";
        const tr = tf.textRange;
        tr.paragraphFormat.horizontalAlignment = "Left";
        tr.font.name = this.config.fonte;
        tr.font.size = this.config.tamFonte;
        tr.font.bold = false;
        tr.font.color = geo.cFutura;
        for (let k = 0; k < n; k++) {
            if (k > kAtual - 1)
                continue;
            const chars = tr.getSubstring(ini[k], tam[k]);
            if (k < kAtual - 1) {
                chars.font.color = geo.cPassada;
            }
            else {
                chars.font.color = geo.cAtual;
                chars.font.bold = true;
            }
        }
        // addTextBox pode ajustar a caixa ao texto; reaplica a geometria
        shp.left = geo.x;
        shp.top = geo.y;
        shp.width = geo.larg;
        shp.height = geo.alt;
        return shp;
    }
    calcularGeometriaECores(posicao, W, H) {
        const TOPO_FAIXA_ALT_PT = (this.config.topoFaixaAltCm / 2.54) * 72;
        let x, y, larg, alt;
        let cAtual, cPassada, cFutura;
        if (posicao === "topo") {
            x = this.config.margemEsq;
            larg = W - 2 * this.config.margemEsq;
            switch (this.config.topoFaixa) {
                case "escura":
                    y = H * TITULO_BASE_REL;
                    alt = TOPO_FAIXA_ALT_PT;
                    cAtual = this.config.rAtual;
                    cPassada = this.config.rPassada;
                    cFutura = this.config.rFutura;
                    break;
                case "clara":
                    y = H * TITULO_BASE_REL;
                    alt = TOPO_FAIXA_ALT_PT;
                    cAtual = this.config.cAtual;
                    cPassada = this.config.cPassada;
                    cFutura = this.config.cFutura;
                    break;
                default:
                    y = H * (TITULO_BASE_REL + TOPO_FOLGA_REL);
                    alt = H * TOPO_ALT_REL;
                    cAtual = this.config.tAtual;
                    cPassada = this.config.tPassada;
                    cFutura = this.config.tFutura;
            }
        }
        else {
            x = this.config.margemEsq;
            y = H * RODAPE_TOPO_REL;
            larg = W - this.config.margemEsq - this.config.reservaDir;
            alt = H * RODAPE_ALT_REL;
            cAtual = this.config.rAtual;
            cPassada = this.config.rPassada;
            cFutura = this.config.rFutura;
        }
        return { x, y, larg, alt, cAtual, cPassada, cFutura };
    }
    montarTextoSumario(secoes, n, kAtual, compacto) {
        const ini = [];
        const tam = [];
        let txt = "";
        for (let k = 0; k < n; k++) {
            let rot;
            if (!compacto) {
                rot = secoes[k].name;
            }
            else if (k === kAtual - 1) {
                rot = `${k + 1}  ${secoes[k].name}`;
            }
            else {
                rot = `${k + 1}`;
            }
            if (k > 0)
                txt += this.config.separador;
            ini[k] = txt.length;
            tam[k] = rot.length;
            txt += rot;
        }
        return { txt, ini, tam };
    }
    // =====================================================================
    // LINHA DE PROGRESSO
    // =====================================================================
    desenharProgressoSlide(slide, pos, total, posicao, W, H) {
        let y;
        if (posicao === "topo") {
            if (this.config.topoFaixa === "nenhuma") {
                y = H * TITULO_BASE_REL - this.config.espLinha;
            }
            else {
                y = H * TITULO_BASE_REL - this.config.espLinha / 2;
            }
        }
        else {
            y = H * RODAPE_TOPO_REL;
        }
        // Sem API de animação: a barra é desenhada inteira (sem o wipe da macro VBA)
        const xAtu = (W * pos) / total;
        const shp = slide.shapes.addGeometricShape("Rectangle", {
            left: 0,
            top: y,
            width: xAtu,
            height: this.config.espLinha,
        });
        shp.name = "Progresso";
        shp.tags.add(TAG_NOME, "1");
        shp.fill.setSolidColor(this.config.corDestaque);
        shp.lineFormat.visible = false;
    }
    // =====================================================================
    // UTILITÁRIOS
    // =====================================================================
    /** Apaga as formas marcadas com a tag do sumário (inclusive as criadas pela macro VBA) */
    async removerElementos(context, slides) {
        const colecoes = slides.map((slide) => {
            const shapes = slide.shapes;
            shapes.load("items/id");
            return shapes;
        });
        await context.sync();
        const verificacoes = colecoes.flatMap((shapes) => shapes.items.map((shape) => {
            const tagNova = shape.tags.getItemOrNullObject(TAG_NOME);
            const tagAntiga = shape.tags.getItemOrNullObject(TAG_ANTIGA);
            tagNova.load("key");
            tagAntiga.load("key");
            return { shape, tagNova, tagAntiga };
        }));
        await context.sync();
        for (const { shape, tagNova, tagAntiga } of verificacoes) {
            if (!tagNova.isNullObject || !tagAntiga.isNullObject) {
                shape.delete();
            }
        }
    }
    // =====================================================================
    // UI HELPERS
    // =====================================================================
    async refreshSectionsList() {
        if (!this.ui)
            return;
        try {
            const estrutura = await lerSecoes();
            const layouts = await PowerPoint.run(async (context) => {
                const slides = context.presentation.slides;
                slides.load("items/layout/name");
                await context.sync();
                return slides.items.map((s) => s.layout.name);
            });
            const secoesData = estrutura.secoes.map((sec, idx) => ({
                index: idx + 1,
                name: sec.name,
                count: sec.slideCount,
                ignored: this.secaoIgnorada(sec.name),
                hasDivider: layouts.some((layout, i) => estrutura.secaoDoSlide[i] === idx && layout === this.config.layoutSemSumario),
            }));
            this.ui.renderSectionsList(secoesData);
            this.ui.updateSectionCount(secoesData.length);
        }
        catch (error) {
            console.warn("Não foi possível carregar seções:", error);
            this.ui.renderSectionsList([]);
            this.ui.updateSectionCount(0);
        }
    }
    // =====================================================================
    // PRESETS
    // =====================================================================
    getConfig() {
        return { ...this.config };
    }
    setConfig(config) {
        this.config = { ...this.config, ...config };
        this.configManager.save(this.config);
        this.ui?.updateControls(this.config);
    }
    exportConfig() {
        return JSON.stringify(this.config, null, 2);
    }
    importConfig(json) {
        try {
            const imported = JSON.parse(json);
            this.setConfig(imported);
            return true;
        }
        catch {
            return false;
        }
    }
}
