// =====================================================================
// Sumário Dinâmico - Gerenciador de Configuração
// Persistência via localStorage
// =====================================================================
const SETTINGS_KEY = "sumarioDinamicoConfig";
export class ConfigManager {
    // roamingSettings só existe no Outlook; no PowerPoint usamos o localStorage,
    // compartilhado entre o painel e os botões da fita (mesma origem)
    async load() { }
    getConfig() {
        try {
            const stored = localStorage.getItem(SETTINGS_KEY);
            if (stored) {
                return JSON.parse(stored);
            }
        }
        catch (error) {
            console.warn("Erro ao carregar configurações:", error);
        }
        return {};
    }
    save(config) {
        try {
            localStorage.setItem(SETTINGS_KEY, JSON.stringify(config));
        }
        catch (error) {
            console.warn("Falha ao salvar configurações:", error);
        }
    }
    clear() {
        try {
            localStorage.removeItem(SETTINGS_KEY);
        }
        catch (error) {
            console.warn("Falha ao limpar configurações:", error);
        }
    }
}
